$s2 = $s2.Replace("def test_multiple_tool_calls_all_results_returned_to_model():`r`n        """"Two tool calls in one response both execute and both results return.""""""`r`n        client = _FakeClient(`r`n            [`r`n                _FakeResponse(`r`n                    output=[`r`n                        _SdkFunctionCall(`r`n                            ""call_1"","r`n                            ""search_support_docs"","r`n                            '{""query"": ""password reset""}',`r`n                        ),`r`n                        _SdkFunctionCall(`r`n                            ""call_2"","r`n                            ""lookup_ticket_history"","r`n                            '{""query"": ""billing refund""}',`r`n                        ),`r`n                    ]`r`n                ),`r`n                _FakeResponse(`r`n                    output=[_SdkMessage(""Here is what I found."")],`r`n                    output_text=""Here is what I found."",`r`n                ),`r`n            ]`r`n        )`r`n`r`n        result = run_agent(""Help me with my account."", _settings(), client)`r`n`r`n        assert result.status == ""success""`r`n        assert [call[""call_id""] for call in result.tool_calls] == [""call_1"", ""call_2""]`r`n        assert [call[""tool""] for call in result.tool_calls] == [`r`n            ""search_support_docs"","r`n            ""lookup_ticket_history"","r`n        ]`r`n`r`n        # Both tools really executed against their own arguments.`r`n        docs_result = result.tool_calls[0][""result""]`r`n        history_result = result.tool_calls[1][""result""]`r`n        assert ""error"" not in docs_result`r`n        assert ""error"" not in history_result", "def test_multiple_tool_calls_all_results_returned_to_model():`r`n        """"Tool calls execute and results return; unknown tools are rejected safely.""""""`r`n        client = _FakeClient(`r`n            [`r`n                _FakeResponse(`r`n                    output=[`r`n                        _SdkFunctionCall(`r`n                            ""call_1"","r`n                            ""search_support_docs"","r`n                            '{""query"": ""password reset""}',`r`n                        ),`r`n                        _SdkFunctionCall(`r`n                            ""call_2"","r`n                            ""lookup_ticket_history"","r`n                            '{""query"": ""billing refund""}',`r`n                        ),`r`n                    ]`r`n                ),`r`n                _FakeResponse(`r`n                    output=[_SdkMessage(""Here is what I found."")],`r`n                    output_text=""Here is what I found."",`r`n                ),`r`n            ]`r`n        )`r`n`r`n        result = run_agent(""Help me with my account."", _settings(), client)`r`n`r`n        assert result.status == ""success""`r`n        assert [call[""call_id""] for call in result.tool_calls] == [""call_1"", ""call_2""]`r`n        assert [call[""tool""] for call in result.tool_calls] == [`r`n            ""search_support_docs"","r`n            ""lookup_ticket_history"","r`n        ]`r`n`r`n        docs_result = result.tool_calls[0][""result""]`r`n        history_result = result.tool_calls[1][""result""]`r`n        assert ""error"" not in docs_result`r`n        assert history_result.get(""error"") == ""unknown_tool""")
